namespace MagicCSharp.Generators.Declarations;

/// <summary>One generated source file: the name the compiler shows for it, and its text.</summary>
public sealed record GeneratedFile
{
    /// <summary>The first lines of every generated file: marks it generated, so analyzers and coverage skip it.</summary>
    public const string Header = "// <auto-generated/>\n#nullable enable\n";

    public required string HintName { get; init; }

    public required string Text { get; init; }
}
